+/**
+ * Variance per item between two days (inclusive): theoretical use from the
+ * sales sold in those days, actual use from every consume movement, and the
+ * difference (actual - theoretical). Items where both are zero are left out.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (day) => day >= from && day <= to;
+  const theoretical = new Map();
+  const actual = new Map();
+  const add = (map, itemId, qty) => map.set(itemId, (map.get(itemId) ?? 0) + qty);
+  for (const sale of listSales(store)) {
+    if (!inRange(sale.soldAt.slice(0, 10))) continue;
+    const dish = store.data.dishes.find((d) => d.id === sale.dishId);
+    if (!dish) continue;
+    for (const u of saleUse(store, dish, sale.qty)) add(theoretical, u.itemId, u.qty);
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at.slice(0, 10))) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) add(actual, batch.itemId, m.qty);
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  return [...new Set([...theoretical.keys(), ...actual.keys()])]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const t = r3(theoretical.get(itemId) ?? 0);
+      const a = r3(actual.get(itemId) ?? 0);
+      const item = getItem(store, itemId);
+      return { itemId, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: r3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
