@@ -0,0 +1,59 @@
+// Sales from the till. Each dish sold uses one portion of its recipe per
+// unit of `qty`. A ticket is booked once; booking is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** Every recorded sale line, in id order. */
+export function listSales(store) {
+  return [...(store.data.sales ?? [])].sort((a, b) => a.id - b.id);
+}
+
+/** True when a ticket has already been booked. */
+export function isTicketBooked(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Ingredient quantities used by selling `qty` of a dish. */
+export function saleUse(store, dish, qty) {
+  return scaled(getRecipe(store, dish.recipeId), qty);
+}
+
+/**
+ * Books sale lines [{ row, ticket, soldAt, dishId, qty }] whose dishes exist.
+ * Lines of tickets already booked are skipped. Checks stock for every line
+ * first and throws import_out_of_stock naming the row (changing nothing);
+ * then consumes per ticket with ref `sale:<ticket>`. Returns { tickets, dishes }.
+ */
+export function bookSales(store, lines) {
+  const fresh = lines.filter((l) => !isTicketBooked(store, l.ticket));
+  const needed = new Map();
+  const perTicket = new Map();
+  for (const line of fresh) {
+    const dish = store.data.dishes.find((d) => d.id === line.dishId);
+    const use = saleUse(store, dish, line.qty);
+    const ticketUse = perTicket.get(line.ticket) ?? { soldAt: line.soldAt, items: new Map() };
+    perTicket.set(line.ticket, ticketUse);
+    for (const u of use) {
+      const total = round3((needed.get(u.itemId) ?? 0) + u.qty);
+      const available = round3(onHand(store, u.itemId));
+      if (total > available) {
+        const item = getItem(store, u.itemId);
+        const left = round3(Math.max(0, available - (needed.get(u.itemId) ?? 0)));
+        throw new AppError("import_out_of_stock", { row: line.row, available: left, unit: item.unit, item: item.name });
+      }
+      needed.set(u.itemId, total);
+      ticketUse.items.set(u.itemId, round3((ticketUse.items.get(u.itemId) ?? 0) + u.qty));
+    }
+  }
+  for (const [ticket, t] of perTicket)
+    for (const [itemId, qty] of t.items)
+      if (qty > 0) consume(store, itemId, qty, { at: t.soldAt, ref: `sale:${ticket}` });
+  store.data.sales ??= [];
+  for (const line of fresh)
+    store.data.sales.push({ id: store.nextId("sale"), ticket: line.ticket, soldAt: line.soldAt, dishId: line.dishId, qty: line.qty });
+  return { tickets: perTicket.size, dishes: fresh.reduce((s, l) => s + l.qty, 0) };
+}
